import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';

// Light cannon — 75mm M6-inspired, generated by scripts/modelgen/light_gun_75mm.py.

export default {
  id: 'light-gun-75mm',
  name: '75mm M6',
  category: 'cannon',
  stats: {
    caliber: 75,
    barrelLength: 2.10,
    elevation: 20,
    depression: 10,
  },

  async build(scene, material) {
    const result = await SceneLoader.ImportMeshAsync(
      '', '/assets/models/tanks/parts/', 'light_gun_75mm.glb', scene
    );

    const root = new TransformNode('gunLight75_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) {
      m.setParent(root);
      m.material = material;
    }

    root.rotation.x = Math.PI / 2;

    return { root, meshes, breech: new Vector3(0, 0, 0) };
  },
};
